import { Router, Request, Response } from 'express';
import { z } from 'zod';

const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine(value => {
  const date = new Date(`${value}T00:00:00.000Z`);
  return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === value;
}, 'must be a valid calendar date');

const querySchema = z.object({
  from: isoDate,
  to: isoDate,
  groupBy: z.enum(['workspace', 'service']),
  limit: z.coerce.number().int().min(1).max(100).default(50),
  cursor: z.string().min(1).optional(),
}).strict().superRefine((query, context) => {
  const from = new Date(`${query.from}T00:00:00.000Z`).getTime();
  const to = new Date(`${query.to}T00:00:00.000Z`).getTime();
  if (from > to) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['from'], message: 'must not be later than to' });
  } else if ((to - from) / 86_400_000 + 1 > 31) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['to'], message: 'date range must not exceed 31 days' });
  }
});

type ReportQuery = z.infer<typeof querySchema>;
interface UsageReportRow {
  groupId: string;
  requestCount: number;
  billableUnits: number;
}
interface UsageReportService {
  list(query: ReportQuery): Promise<{ items: UsageReportRow[]; nextCursor: string | null }>;
}

export function createUsageReportRouter(service: UsageReportService): Router {
  const router = Router();

  router.get('/v1/usage/reports', async (req: Request, res: Response) => {
    const parsed = querySchema.safeParse(req.query);
    if (!parsed.success) {
      const details = parsed.error.issues.map(issue => `${issue.path.join('.')}: ${issue.message}`);
      return res.status(400).json({ error: 'invalid_query', details });
    }

    const page = await service.list(parsed.data);
    return res.status(200).json(page);
  });

  return router;
}

import { Router, Request, Response } from 'express';
import { z } from 'zod';

const paramsSchema = z.object({ shipmentId: z.string().min(1) });
const bodySchema = z.object({
  carrierCode: z.string().regex(/^[A-Z0-9-]{2,20}$/),
  trackingReference: z.string().min(5).max(40),
}).strict();

type DispatchDetails = z.infer<typeof bodySchema>;
interface ShipmentRepository {
  findById(shipmentId: string): Promise<{ id: string; status: string } | null>;
  markDispatched(shipmentId: string, details: DispatchDetails): Promise<void>;
}

export function createShipmentRouter(repository: ShipmentRepository): Router {
  const router = Router();

  router.post('/v1/shipments/:shipmentId/dispatch', async (req: Request, res: Response) => {
    const params = paramsSchema.safeParse(req.params);
    const body = bodySchema.safeParse(req.body);
    if (!params.success || !body.success) {
      const details = [
        ...(params.success ? [] : params.error.issues.map(issue => `params.${issue.path.join('.')}: ${issue.message}`)),
        ...(body.success ? [] : body.error.issues.map(issue => `body.${issue.path.join('.')}: ${issue.message}`)),
      ];
      return res.status(400).json({ error: 'invalid_request', details });
    }

    const shipment = await repository.findById(params.data.shipmentId);
    if (!shipment) {
      return res.status(404).json({ error: 'shipment_not_found' });
    }
    if (shipment.status !== 'ready') {
      return res.status(409).json({ error: 'shipment_not_ready' });
    }

    await repository.markDispatched(shipment.id, body.data);
    return res.status(200).json({
      shipmentId: shipment.id,
      status: 'dispatched',
      carrierCode: body.data.carrierCode,
      trackingReference: body.data.trackingReference,
    });
  });

  return router;
}

import { Router, Request, Response } from 'express';
import { z } from 'zod';

const paramsSchema = z.object({
  projectId: z.string().min(1),
  memberId: z.string().min(1),
});
const bodySchema = z.object({
  role: z.enum(['viewer', 'editor', 'admin']),
}).strict();

type MemberRole = z.infer<typeof bodySchema>['role'];
interface MembershipRepository {
  updateRole(projectId: string, memberId: string, role: MemberRole): Promise<{ projectId: string; memberId: string; role: MemberRole } | null>;
}

export function createMemberRouter(repository: MembershipRepository): Router {
  const router = Router();

  router.patch('/v1/projects/:projectId/members/:memberId', async (req: Request, res: Response) => {
    const params = paramsSchema.safeParse(req.params);
    const body = bodySchema.safeParse(req.body);
    if (!params.success || !body.success) {
      const details = [
        ...(params.success ? [] : params.error.issues.map(issue => `params.${issue.path.join('.')}: ${issue.message}`)),
        ...(body.success ? [] : body.error.issues.map(issue => `body.${issue.path.join('.')}: ${issue.message}`)),
      ];
      return res.status(400).json({ error: 'invalid_request', details });
    }

    const membership = await repository.updateRole(
      params.data.projectId,
      params.data.memberId,
      body.data.role,
    );
    if (!membership) {
      return res.status(404).json({ error: 'membership_not_found' });
    }
    return res.status(200).json(membership);
  });

  return router;
}
